use vstd::prelude::*;
use vstd::vec::*;

verus! {

spec fn rotated_seq(seq: Seq<i32>, n: nat) -> Seq<i32>
    requires
        0 < n < seq.len(),
    decreases seq.len(),
{
    if seq.len() == 0 {
        Seq::empty()
    } else {
        // Concatenate seq[n..] with seq[0..n]
        seq.subrange(n as int, seq.len() as int).add(seq.subrange(0, n as int))
    }
}

fn split_and_append(list: &Vec<i32>, n: usize) -> (new_list: Vec<i32>)
    requires
        list.len() > 0,
        0 < n < list.len(),
    ensures
        new_list@.len() == list@.len(),
        new_list@ == rotated_seq(list@, n as nat),
{
    let mut new_list = Vec::new();
    let len = list.len();
    
    // First copy elements from n to end
    let mut i = n;
    while i < len
        invariant
            n <= i <= len,
            new_list@.len() == i - n,
            forall|k: int| 0 <= k < i - n ==> new_list@[k] == list@[n + k],
        decreases len - i,
    {
        new_list.push(list[i]);
        i = i + 1;
    }
    
    // Then copy elements from 0 to n
    let mut j = 0;
    while j < n
        invariant
            0 <= j <= n,
            new_list@.len() == (len - n) + j,
            forall|k: int| 0 <= k < len - n ==> new_list@[k] == list@[n + k],
            forall|k: int| 0 <= k < j ==> new_list@[(len - n) + k] == list@[k],
        decreases n - j,
    {
        new_list.push(list[j]);
        j = j + 1;
    }
    
    new_list
}

}
